// Rotate through 6 post angle types to keep content fresh
const angles = ['job_spotlight', 'seasonal_offer', 'local_faq', 'community', 'behind_the_scenes', 'milestone'];
const weekNumber = Math.floor(Date.now() / (7 * 24 * 60 * 60 * 1000));
const angleIndex = weekNumber % angles.length;
const thisWeekAngle = angles[angleIndex];

// Get this month's season (AU seasons)
const month = new Date().getMonth() + 1;
let season = 'autumn';
if (month >= 12 || month <= 2) season = 'summer';
else if (month >= 3 && month <= 5) season = 'autumn';
else if (month >= 6 && month <= 8) season = 'winter';
else season = 'spring';

return $input.all().map(item => ({
  json: { ...item.json, post_angle: thisWeekAngle, current_season: season }
}));

